package playerweb

// CollectionHTML is Player's canonical accessible curation page.
const CollectionHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{{.Name}} · Kinosail Player</title><script src="/static/theme.js?v=cinema-1"></script><link rel="stylesheet" href="/static/app.css?v=cinema-1"></head><body class="detail-page"><main class="detail-shell collection-detail collection-page"><a class="back" href="/?view=collections">{{icon "back"}} Collections</a><span class="eyebrow">Collection</span><h1>{{.Name}}</h1><p>{{.ItemCount}} items</p><div class="grid collection-items">{{range $position, $item := .Items}}<article class="card"><a href="{{if eq $item.Kind "book"}}/book/{{$item.ID}}{{else}}/watch/{{$item.ID}}{{end}}">{{if $item.Artwork}}<img class="poster" src="/art/{{$item.ID}}" alt="" width="400" height="600" decoding="async" {{if lt $position 2}}fetchpriority="high"{{else}}loading="lazy"{{end}}>{{else}}<div class="poster">{{icon "collection"}}</div>{{end}}<h2>{{$item.Title}}</h2></a>{{if $.Owner}}<form action="/collection/{{$.Name}}/items/{{$item.ID}}" method="post"><input type="hidden" name="included" value="false"><button class="quiet">Remove</button></form>{{end}}</article>{{else}}<div class="empty"><h2>This Collection is empty.</h2><p>Search below to add something.</p></div>{{end}}</div>{{if .Owner}}<section class="collection-editor" id="collection-search"><span class="eyebrow">Curate</span><h2>Add to {{.Name}}</h2><form action="/collection/{{.Name}}" role="search" aria-label="Find something"><label for="collection-query">Find something</label><input id="collection-query" name="q" value="{{.Query}}" placeholder="Title, artist, genre…" maxlength="200"><button>Find</button></form>{{if .Query}}<div class="grid collection-results">{{range $position, $item := .Candidates}}<article class="card">{{if $item.Artwork}}<img class="poster" src="/art/{{$item.ID}}" alt="" width="400" height="600" decoding="async" {{if lt $position 2}}fetchpriority="high"{{else}}loading="lazy"{{end}}>{{else}}<div class="poster">{{icon "collection"}}</div>{{end}}<h2>{{$item.Title}}</h2><form action="/collection/{{$.Name}}/items/{{$item.ID}}" method="post"><input type="hidden" name="included" value="true"><input type="hidden" name="q" value="{{$.Query}}"><button>Add to</button></form></article>{{else}}<div class="empty"><h2>Nothing found.</h2><p>Add media or try another search.</p></div>{{end}}</div>{{end}}</section><details><summary class="danger">Delete {{.Name}}?</summary><p>This permanently deletes the Collection.</p><form action="/collection/{{.Name}}/delete" method="post"><button class="danger">Delete Collection</button></form></details>{{end}}</main></body></html>`

// PlaylistHTML is Player's canonical accessible curation page.
const PlaylistHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{{.Name}} · Kinosail Player</title><script src="/static/theme.js?v=cinema-1"></script><link rel="stylesheet" href="/static/app.css?v=cinema-1"></head><body class="detail-page"><main class="detail-shell collection-detail"><a class="back" href="/?view=playlists">{{icon "back"}} Playlists</a><span class="eyebrow">{{.Mode}} playlist</span><h1>{{.Name}}</h1><p>{{.ItemCount}} items{{if .Rule}} · {{.Rule}}{{end}}</p>{{if .Smart}}<div class="curation-note"><strong>Updates automatically</strong><span>This playlist follows its rule whenever your Library changes.</span></div>{{end}}<div class="grid collection-items">{{range $position, $item := .Items}}<article class="card"><a href="{{if eq $item.Kind "book"}}/book/{{$item.ID}}{{else}}/watch/{{$item.ID}}{{end}}">{{if or $item.Artwork $item.ShowArtwork}}<img class="poster" src="/art/{{$item.ID}}" alt="" width="400" height="600" decoding="async" {{if lt $position 2}}fetchpriority="high"{{else}}loading="lazy"{{end}}>{{else}}<div class="poster">{{icon "play"}}</div>{{end}}<h2>{{$item.Title}}</h2>{{if $item.Artist}}<small>{{$item.Artist}}</small>{{end}}</a>{{if not $.Smart}}<div class="playlist-order">{{if $item.CanEarlier}}<form action="/playlist/{{$.Name}}/order" method="post"><input type="hidden" name="id" value="{{$item.ID}}"><button class="quiet" name="direction" value="up" aria-label="Move {{$item.Title}} earlier">↑</button></form>{{end}}{{if $item.CanLater}}<form action="/playlist/{{$.Name}}/order" method="post"><input type="hidden" name="id" value="{{$item.ID}}"><button class="quiet" name="direction" value="down" aria-label="Move {{$item.Title}} later">↓</button></form>{{end}}<form action="/playlist/{{$.Name}}/items/{{$item.ID}}" method="post"><input type="hidden" name="included" value="false"><button class="quiet">Remove</button></form></div>{{end}}</article>{{else}}<div class="empty"><h2>This playlist is empty.</h2><p>{{if .Smart}}Nothing matches its rule yet.{{else}}Search below to add something.{{end}}</p></div>{{end}}</div>{{if not .Smart}}<section class="collection-editor" id="playlist-search"><span class="eyebrow">Curate</span><h2>Add to {{.Name}}</h2><form action="/playlist/{{.Name}}" role="search" aria-label="Find something"><label for="playlist-query">Find something</label><input id="playlist-query" name="q" value="{{.Query}}" placeholder="Title, artist, genre…" maxlength="200"><button>Find</button></form>{{if .Query}}<div class="grid collection-results">{{range $position, $item := .Candidates}}<article class="card">{{if or $item.Artwork $item.ShowArtwork}}<img class="poster" src="/art/{{$item.ID}}" alt="" width="400" height="600" decoding="async" {{if lt $position 2}}fetchpriority="high"{{else}}loading="lazy"{{end}}>{{else}}<div class="poster">{{icon "play"}}</div>{{end}}<h2>{{$item.Title}}</h2><form action="/playlist/{{$.Name}}/items/{{$item.ID}}" method="post"><input type="hidden" name="included" value="true"><input type="hidden" name="q" value="{{$.Query}}"><button>Add to</button></form></article>{{else}}<div class="empty"><h2>Nothing found.</h2><p>Try another title, person, or genre.</p></div>{{end}}</div>{{end}}</section>{{end}}<details><summary class="danger">Delete {{.Name}}?</summary><p>This permanently deletes the playlist.</p><form action="/playlist/{{.Name}}/delete" method="post"><button class="danger">Delete playlist</button></form></details></main></body></html>`
